class Solution {
  public int maxSumDivThree(int[] nums) {
    int[] dp = {0, Integer.MIN_VALUE, Integer.MIN_VALUE}; // best sum seen with each remainder mod 3
    for (int x : nums) {
      int[] next = dp.clone();
      for (int r = 0; r < 3; r++) {
        if (dp[r] == Integer.MIN_VALUE) continue;
        int s = dp[r] + x;
        next[s % 3] = Math.max(next[s % 3], s);
      }
      dp = next;
    }
    return dp[0];
  }
}
